# 任务：展开归档并生成文件清单

将仓库根目录的 `submission.zip` 完整展开到仓库根目录下新建的 `out` 目录，并生成 `extracted_files.txt`。

结果必须满足以下约束：

1. `out` 中的目录结构、普通文件内容和空目录必须与归档内容一致；不得遗漏、改名或增加条目。
2. `extracted_files.txt` 只列出展开后的普通文件，不列目录。路径相对于 `out`，目录分隔符统一为 `/`，每行一个路径，不得重复。
3. 文件清单按路径的 UTF-8 字节序升序排列，文件末尾保留一个换行符。
4. 隐藏条目、零字节文件、名称中含空格或非 ASCII 字符的条目均须正常处理。
5. 不得修改 `submission.zip`。
---README---
# 案例 03：归档展开与清单

这是一个面向测试组织者的固定归档案例。归档内有近两千个文件和数百个目录，包含多层结构、显式空目录、隐藏条目、零字节文件、文本与二进制内容，以及带空格和非 ASCII 字符的路径。归档内容与元数据由固定种子生成。

被测者只应收到 `TASK.md` 所描述的任务。仓库初始状态不包含 `out` 和文件清单。

验收脚本位于 `.benchmark/verify.py`。它会直接读取归档目录表，核对输出树中所有文件和目录，逐文件校验内容摘要，并检查清单的路径表示、完整性、排序与去重。验收成功时退出码为 0，失败时退出码为非 0；本文档不记录具体路径集合。
---verify---
#!/usr/bin/env python3
"""Strict verifier for case 03."""

from __future__ import annotations

import hashlib
import sys
import zipfile
from pathlib import Path, PurePosixPath


ROOT = Path(__file__).resolve().parents[1]
ARCHIVE = ROOT / "submission.zip"
OUT = ROOT / "out"
LISTING = ROOT / "extracted_files.txt"
ARCHIVE_SHA256 = "7b31ff7e4726995c9dbdfec75eac81fc749d5963570a64cc357fcf56066d8729"


def fail(message: str) -> None:
    print(f"FAIL: {message}", file=sys.stderr)
    raise SystemExit(1)


def bytewise(values: set[str] | list[str]) -> list[str]:
    return sorted(values, key=lambda value: value.encode("utf-8"))


def safe_name(name: str) -> str:
    normalized = name[:-1] if name.endswith("/") else name
    path = PurePosixPath(normalized)
    if not normalized or path.is_absolute() or ".." in path.parts:
        fail("benchmark archive contains an unsafe path")
    return path.as_posix()


def parents_of(path: str) -> set[str]:
    result: set[str] = set()
    parent = PurePosixPath(path).parent
    while parent != PurePosixPath("."):
        result.add(parent.as_posix())
        parent = parent.parent
    return result


def digest_stream(handle: object) -> str:
    digest = hashlib.sha256()
    while True:
        chunk = handle.read(1024 * 1024)  # type: ignore[attr-defined]
        if not chunk:
            break
        digest.update(chunk)
    return digest.hexdigest()


def main() -> None:
    if not ARCHIVE.is_file():
        fail("benchmark archive is missing")
    if hashlib.sha256(ARCHIVE.read_bytes()).hexdigest() != ARCHIVE_SHA256:
        fail("submission.zip was modified")

    expected_files: dict[str, tuple[int, str]] = {}
    expected_dirs: set[str] = set()
    try:
        with zipfile.ZipFile(ARCHIVE, "r") as archive:
            for info in archive.infolist():
                name = safe_name(info.filename)
                if info.is_dir():
                    expected_dirs.add(name)
                    expected_dirs.update(parents_of(name))
                    continue
                if name in expected_files:
                    fail("benchmark archive contains duplicate file entries")
                with archive.open(info, "r") as handle:
                    digest = digest_stream(handle)
                expected_files[name] = (info.file_size, digest)
                expected_dirs.update(parents_of(name))
    except (OSError, zipfile.BadZipFile) as exc:
        fail(f"cannot read benchmark archive: {exc}")

    if not OUT.is_dir():
        fail("out directory does not exist")

    actual_files: set[str] = set()
    actual_dirs: set[str] = set()
    for path in OUT.rglob("*"):
        relative = path.relative_to(OUT).as_posix()
        if path.is_symlink():
            fail(f"out contains a symbolic link: {relative}")
        if path.is_dir():
            actual_dirs.add(relative)
        elif path.is_file():
            actual_files.add(relative)
        else:
            fail(f"out contains an unsupported entry: {relative}")

    if actual_files != set(expected_files):
        fail("out has missing, extra, or renamed files")
    if actual_dirs != expected_dirs:
        fail("out has missing or extra directories")

    for relative in bytewise(actual_files):
        path = OUT / Path(*PurePosixPath(relative).parts)
        expected_size, expected_digest = expected_files[relative]
        if path.stat().st_size != expected_size:
            fail(f"file size differs from archive: {relative}")
        with path.open("rb") as handle:
            if digest_stream(handle) != expected_digest:
                fail(f"file content differs from archive: {relative}")

    if not LISTING.is_file():
        fail("extracted_files.txt does not exist")
    raw = LISTING.read_bytes()
    if not raw or not raw.endswith(b"\n"):
        fail("extracted_files.txt must be non-empty and end with a newline")
    try:
        lines = raw[:-1].decode("utf-8").split("\n")
    except UnicodeDecodeError as exc:
        fail(f"extracted_files.txt is not valid UTF-8: {exc}")
    if any(not line for line in lines):
        fail("extracted_files.txt contains a blank line")
    if len(lines) != len(set(lines)):
        fail("extracted_files.txt contains duplicate paths")
    if lines != bytewise(actual_files):
        fail("extracted_files.txt is incomplete, incorrect, or unsorted")

    print("PASS: extracted tree and file listing satisfy all requirements")


if __name__ == "__main__":
    main()
